import java.util.*;

public class RodzinyKluczy {
    static String rodzina(String klucz) {
        String[] czesci = klucz.split(":", -1);
        for (int i = 0; i < czesci.length; i++) {
            if (czesci[i].matches("\\d+") || czesci[i].matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}")) {
                czesci[i] = "{id}";
            }
        }
        return String.join(":", czesci);
    }

    public static void main(String[] args) {
        List<String> klucze = List.of("user:42", "user:17", "user:42:sessions", "user:17:sessions",
            "leaderboard:weekly", "cache:product:991", "cache:product:12",
            "session:3f2b8c1e-9a7d-4e21-b6c3-0d1e2f3a4b5c", "user:99");
        Map<String, Integer> rodziny = new TreeMap<>();
        for (String k : klucze) rodziny.merge(rodzina(k), 1, Integer::sum);
        rodziny.forEach((r, n) -> System.out.println(n + "\t" + r));
    }
}
// 2  cache:product:{id}
// 1  leaderboard:weekly
// 1  session:{id}
// 3  user:{id}
// 2  user:{id}:sessions
